def generator(rng):
    # Choose m in a range that keeps the instance nontrivial yet computationally verifiable.
    # m=4 reproduces the seed's scale; m=5 increases difficulty substantially.
    m = rng.choice([4, 5])
    total_points = (m + 1) * (m + 2) // 2
    # Return assignments used by the wrapper and verifier.
    return {
        'm': m,
        'total_points': total_points
    }
